def paper_structure_partition {Data Candidate : Type*}
    (constraints : paper_structure_constraints Data Candidate) : Prop :=
  rcvStructurePartition constraints

def paper_smart_allocation_slack_filling_operation_count {Slack : Type*}
    (problem : paper_smart_allocation_slack_filling_problem Slack) : ℕ :=
  problem.uniqueBallotCount * problem.candidateCount

def paper_sequence_reduction_concrete_coverage_specification {Sequence : Type*}
    (feasibleSequence : Sequence → Prop) (reduced : Finset Sequence) : Prop :=
  sequenceReductionConcreteCoverageSpecification feasibleSequence reduced

def paper_coalition_all_benefit {Candidate : Type*}
    (coalition : Finset Candidate) (benefits : Candidate → Prop) : Prop :=
  coalitionAllBenefit coalition benefits

def paper_exante_coalition_all_benefit_possible {Candidate : Type*}
    (coalition : Finset Candidate) (benefits : Candidate → Prop) : Prop :=
  exAnteCoalitionAllBenefitPossible coalition benefits

def paper_always_expost_beneficial {State : Type*}
    (benefit : State → Prop) : Prop :=
  alwaysExPostBeneficial benefit

def paper_may_be_expost_disadvantageous {State : Type*}
    (disadvantage : State → Prop) : Prop :=
  mayBeExPostDisadvantageous disadvantage

def paper_feasible_sequence_win_count_bound (sequence : paper_rcv_sequence)
    (k : ℕ) : Prop :=
  feasibleSequenceWinCountBound sequence k

def paper_feasible_sequence_family_win_bound {rounds : ℕ}
    (sequences : Finset (paper_rcv_fixed_length_sequence rounds)) (k : ℕ) : Prop :=
  feasibleSequenceFamilyWinBound sequences k

theorem paper_lemmaB2_round_winning_never_election_loser {Candidate : Type*}
    [DecidableEq Candidate] {roundWinners : Finset Candidate}
    {outcome : RCVWinLossStructure Candidate}
    (hsubset : roundWinners ⊆ outcome.winners) :
    paper_round_winning_candidates_never_election_losers roundWinners outcome := by
  exact lemmaB2_roundWinning_never_electionLoser_of_subset hsubset
